Q: How to read excel file by row in Go language? A: <p>Excelize offers the ability to <em>stream data and read it in chunks</em>, saving RAM: The stream writer will try to use temporary files on disk to reduce the memory usage when in-memory chunks data are over 16MB.</p>
<p>Watch the tutorial: &quot;<a href="https://www.youtube.com/watch?v=mzQhoVrKOz8" rel="nofollow noreferrer">Create a Million Cells Worksheet by Stream Writer</a>&quot; tutorial on YouTube.</p>
<p>Below is the initial, simple, and <strong>working</strong> code; the complete code for the &quot;huge table&quot; (producing a 30MB .xlsx file in seconds, 102400 rows x 50 cols), on the other hand, can be copied from the Excelize documentation regarding &quot;NewStreamWriter()&quot;, you can see an excerpt below, from a working codebase.</p>
<pre><code>package main

import (
    &quot;fmt&quot;
    &quot;github.com/xuri/excelize/v2&quot;
)

func main() {

    type any = interface{}

    /*
        Cell can be used directly in StreamWriter.SetRow to specify a style and a value.
        -note- the actual struct is excelize.Cell

        type Cell struct {
            StyleID int
            Formula string
            Value  any // interface{}
        }
    */

    f := excelize.NewFile()
    defer func() {
        if err := f.Close(); err != nil {
            fmt.Println(err)
        }
    }()

    streamWriter, err := f.NewStreamWriter(&quot;Sheet1&quot;)
    if err != nil {
        fmt.Println(err)
        return
    }

    // struct with field Value, Formula, StyleID
    cell1 := excelize.Cell{
        Value: &quot;Merchandise Sales Report&quot;,
    }

    sli1 := []any{cell1}

    err = streamWriter.SetRow(&quot;A1&quot;, sli1)
    if err != nil {
        fmt.Println(err)
        return
    }

    // Set cell value and cell formula for a worksheet with stream writer:
    err = streamWriter.SetRow(&quot;B2&quot;, []any{
        excelize.Cell{Value: 1},
        excelize.Cell{Value: 2},
        excelize.Cell{Formula: &quot;SUM(B2,B3)&quot;},
    },
    )
    if err != nil {
        fmt.Println(err)
        return
    }

    // Set cell value and rows style for a worksheet with stream writer:
    err = streamWriter.SetRow(&quot;B3&quot;, []any{
        excelize.Cell{Value: 6}},
        excelize.RowOpts{
            StyleID: 0,
            Height:  20,
            Hidden:  false,
        },
    )
    if err != nil {
        fmt.Println(err)
        return
    }

    // final Flush() and SaveAs, with &quot;defer&quot; that closes and cleans up.
    if err := streamWriter.Flush(); err != nil {
        fmt.Println(err)
        return
    }
    if err := f.SaveAs(&quot;Book3.xlsx&quot;); err != nil {
        fmt.Println(err)
    }

    /*
    // after that, a huge table could be written, excerpt:
    for rowID := 2; rowID &lt;= 102; rowID++ { // -note- was huge, 102400x50, now 102x20
            row := make([]interface{}, 20)
            for colID := 0; colID &lt; 20; colID++ {
                row[colID] = rand.IntN(640000) //-note- bug, was rand.Intn(640000)
            }
            cell, err := excelize.CoordinatesToCellName(1, rowID)
            if err != nil {
                fmt.Println(err)
                break
            }
            if err := sw.SetRow(cell, row); err != nil {
                fmt.Println(err)
                break
            }
        }
    */

}
</code></pre>
